let monitorQuery='';
const monitorNames={http:'HTTP / HTTPS',keyword:'HTTP keyword',json:'HTTP JSON value',tcp:'TCP port',ping:'Ping',dns:'DNS record',tls:'TLS certificate',websocket:'WebSocket upgrade',docker:'Docker container (HTTPS API)',steam:'Steam game server',push:'Push heartbeat',ntp:'NTP time server',redis:'Redis PING',mqtt:'MQTT broker',smtp:'SMTP server',imap:'IMAP server',pop3:'POP3 server'};
function serviceDevices(){return ds().filter(d=>d.integration?.kind==='service')}
function heartbeats(d){return `<div class="heartbeats" role="img" aria-label="Recent monitor checks">${(d.availability?.recent||[]).map(h=>`<i class="beat ${h.up===true?'up':h.up===false?'down':'unknown'}" title="${esc(new Date(h.time*1000).toLocaleString())}: ${h.up===true?'Up':h.up===false?'Down':'Retrying'}${h.responseMs!=null?' · '+h.responseMs+' ms':''}"></i>`).join('')||'<span class="metric-note">Awaiting checks</span>'}</div>`}
function responseChart(d){let values=(d.availability?.recent||[]).filter(h=>h.responseMs!=null);if(!values.length)return '<p class="metric-note">No response-time measurements yet.</p>';let max=Math.max(1,...values.map(h=>h.responseMs)),points=values.map((h,i)=>`${values.length===1?150:i/(values.length-1)*300},${80-h.responseMs/max*70}`).join(' ');return `<h2 class="section">Response time</h2><svg class="spark" viewBox="0 0 300 90" role="img" aria-label="Measured response time"><polyline points="${points}" fill="none" stroke="#7053e8" stroke-width="2"/>${values.length===1?`<circle cx="150" cy="${80-values[0].responseMs/max*70}" r="3" fill="#7053e8"/>`:''}</svg><p class="metric-note">Scale: 0–${max.toFixed(1)} ms · Latest ${values.length} measured checks</p>`}
function monitorsPage(){return `<div class="actions section"><button class="btn primary" data-role="admin" onclick="monitorForm()">＋ Add monitor</button><button class="btn" data-role="admin" onclick="bulkMonitor('pause')">Pause selected</button><button class="btn" data-role="admin" onclick="bulkMonitor('resume')">Resume selected</button></div><section class="card section"><div class="filters"><input class="search" id="monitorSearch" aria-label="Search monitors" placeholder="Search name, group, tag, or type" value="${esc(monitorQuery)}"></div><div id="monitorList"></div></section>`}
function renderMonitorList(){monitorQuery=$('#monitorSearch')?.value||'';let term=monitorQuery.toLowerCase();$('#monitorList').innerHTML=serviceDevices().filter(d=>[d.name,d.integration.monitorType,d.integration.group,...(d.integration.tags||[])].join(' ').toLowerCase().includes(term)).sort((a,b)=>(a.integration.group||'').localeCompare(b.integration.group||'')||a.name.localeCompare(b.name)).map(d=>`<div class="monitorrow"><input type="checkbox" data-monitor-selection="${d.id}" aria-label="Select ${esc(d.name)}" data-role="admin"><button class="monitorlink" onclick="monitorDetail(${d.id})"><strong>${esc(d.name)}</strong><small>${esc(d.integration.group||'Ungrouped')} · ${esc(monitorNames[d.integration.monitorType])} ${(d.integration.tags||[]).map(t=>' · '+esc(t)).join('')}</small>${heartbeats(d)}</button><div><span class="badge ${d.status.toLowerCase()}">${esc(d.status)}</span><p class="metric-note">${metric(d.availability?.day.uptime)} uptime · ${d.responseMs==null?'—':d.responseMs+' ms'}</p></div></div>`).join('')||'<div class="empty">No service monitors yet. Add a monitor to start collecting measurements.</div>';applyRole()}
async function bulkMonitor(action){let ids=[...document.querySelectorAll('[data-monitor-selection]:checked')].map(el=>+el.dataset.monitorSelection);if(!ids.length)return toast('Select at least one monitor.');try{for(let id of ids)await api('/api/monitor-control','POST',{id,action});await refresh();toast('Selected monitors updated.')}catch(e){toast(e.message)}}
function monitorForm(id){if(!state.companies.length)return editCompany();let d=state.devices.find(d=>d.id===id),saved=d?.integration||{},initial=saved.monitorType||'http';modal(`<h1>${id?'Edit':'Add'} monitor</h1><form id="serviceForm"><label for="monitorName">Name</label><input id="monitorName" class="field" name="name" required maxlength="128" value="${esc(d?.name||'')}"><label for="monitorCompany">Company</label><select class="field" id="monitorCompany" name="company">${state.companies.map(c=>`<option ${c===(d?.company||company)?'selected':''}>${esc(c)}</option>`).join('')}</select><label for="monitorType">Monitor type</label><select class="field" id="monitorType" name="monitorType">${Object.entries(monitorNames).map(([v,n])=>`<option value="${v}" ${v===initial?'selected':''}>${n}</option>`).join('')}</select><div id="monitorFields"></div><h2 class="section">Scheduling and organisation</h2>${[['interval','Check / expected heartbeat interval (seconds)',60,20,86400],['timeout','Timeout / heartbeat grace (seconds)',10,1,30],['retries','Retries before down',2,0,10]].map(([k,label,value,min,max])=>`<label for="mon-${k}">${label}</label><input id="mon-${k}" class="field" name="${k}" type="number" min="${min}" max="${max}" required value="${saved[k]??value}">`).join('')}<label for="monitorGroup">Group</label><input class="field" id="monitorGroup" name="group" value="${esc(saved.group||'')}" maxlength="128"><label for="monitorTags">Tags (comma separated)</label><input class="field" id="monitorTags" name="tags" value="${esc((saved.tags||[]).join(', '))}"><label class="formlabel"><input name="notify" type="checkbox" ${saved.notify!==false?'checked':''}> Send alerts using configured notification channels</label><label class="formlabel"><input name="paused" type="checkbox" ${saved.paused?'checked':''}> Pause monitor</label><button class="btn primary">Save monitor</button></form>`);
function fields(){let kind=$('#monitorType').value,c=kind===saved.monitorType?saved:{},f=(k,label,value='',secret=false)=>`<label class="formlabel" for="mon-${k}">${label}</label><input class="field" id="mon-${k}" name="${k}" type="${secret?'password':'text'}" value="${secret?'':esc(c[k]??value)}" placeholder="${secret&&id?'Leave blank to keep saved value':''}">`,html='';if(['http','keyword','json','websocket','docker'].includes(kind)){html+=f('endpoint','Endpoint URL (saved URL stays hidden)','',true);if(c.displayEndpoint)html+='<p class="metric-note">Current endpoint: '+esc(c.displayEndpoint)+'</p>';html+=f('headersJson','Custom headers (JSON; optional)','',true);if(kind!=='websocket')html+='<label for="mon-method">HTTP method</label><select class="field" id="mon-method" name="method">'+['GET','HEAD','POST'].map(v=>`<option ${v===(c.method||'GET')?'selected':''}>${v}</option>`).join('')+'</select>'+f('requestBody','POST request body (optional)','',true)+f('expectedCodes','Accepted HTTP status codes','200-299')+f('proxyUrl','HTTP(S) proxy URL (optional)','',true);html+='<label for="mon-caPem">Private CA certificate PEM (optional)</label><textarea class="field" id="mon-caPem" name="caPem" rows="3">'+esc(c.caPem||'')+'</textarea>'}else if(kind!=='push'){html+=f('host','Hostname or IP');if(['tcp','tls','steam','ntp','redis','mqtt','smtp','imap','pop3'].includes(kind))html+=f('port','Port',({tls:'443',steam:'27015',ntp:'123',redis:'6379',mqtt:'8883',smtp:'587',imap:'993',pop3:'995'}[kind]||'80'))}
if(['redis','mqtt','smtp','imap','pop3'].includes(kind)){html+=f('username','Username (optional)')+f('password','Password (optional)','',true)+'<label for="mon-tlsMode">Transport</label><select class="field" id="mon-tlsMode" name="tlsMode">'+[['tls','TLS'],...(['smtp','imap','pop3'].includes(kind)?[['starttls','STARTTLS']]:[]),['plain','Plain (trusted network)']].map(([v,n])=>`<option value="${v}" ${v===(c.tlsMode||(kind==='smtp'?'starttls':'tls'))?'selected':''}>${n}</option>`).join('')+'</select>'}if(['tls','redis','mqtt','smtp','imap','pop3'].includes(kind))html+='<label for="mon-caPem">Private CA certificate PEM (optional)</label><textarea class="field" id="mon-caPem" name="caPem" rows="3">'+esc(c.caPem||'')+'</textarea>';if(kind==='keyword')html+=f('keyword','Expected keyword')+`<label class="formlabel"><input type="checkbox" name="invert" ${c.invert?'checked':''}> Fail when keyword is present</label>`;if(kind==='json')html+=f('jsonPath','JSON path (for example status.ready)')+f('expectedValue','Expected JSON value (true, 42, or "ok")');if(kind==='dns')html+='<label for="mon-dnsType">Record type</label><select class="field" id="mon-dnsType" name="dnsType">'+['A','AAAA','CNAME','MX','TXT','NS','SOA','SRV','CAA','PTR'].map(v=>`<option ${(c.dnsType||'A')===v?'selected':''}>${v}</option>`).join('')+'</select>'+f('dnsServer','DNS server IP (optional)')+f('expectedValue','Expected answer (optional; exact match)');if(kind==='tls')html+=f('certWarnDays','Warn before certificate expiry (days)','14');if(kind==='docker')html+='<p class="metric-note">Enter a read-only HTTPS Docker inspection URL such as https://host:2376/containers/name/json. Certificates are verified. Docker socket access is not used.</p>';if(kind==='push')html+='<p class="metric-note">Saving creates a private heartbeat URL. Call it within the expected interval plus grace. Missing heartbeats report down. Retry count applies to active checks.</p>';if(kind==='websocket')html+='<p class="metric-note">Checks the protocol upgrade handshake; application messages are not tested.</p>';$('#monitorFields').innerHTML=html}
fields();$('#monitorType').onchange=fields;$('#serviceForm').onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),config={...f,kind:'service',notify:e.target.elements.notify.checked,paused:e.target.elements.paused.checked,invert:!!e.target.elements.invert?.checked,tags:f.tags.split(',').map(x=>x.trim()).filter(Boolean)};for(let k of ['interval','timeout','retries','port','certWarnDays'])if(k in config)config[k]=+config[k];delete config.name;delete config.company;let button=e.target.querySelector('button');button.disabled=true;try{let result=await api('/api/monitors','POST',{...(id?{id}:{}),name:f.name,company:f.company,config});await refresh();closePanel();if(result.pushToken)showPushToken(result.pushToken);else toast('Monitor saved. Checks start automatically.')}catch(e){toast(e.message)}finally{button.disabled=false}}}
function showPushToken(token){modal('<h1>Push heartbeat URL</h1><p>This credential is shown once. Keep it private. Send an HTTP GET or POST after each successful job. Add ?status=down to report a failure.</p><pre id="pushUrl"></pre><p class="metric-note">Rotating the credential revokes the old URL.</p>');$('#pushUrl').textContent=location.origin+'/api/push/'+token}
async function monitorAction(id,action){try{let result=await api('/api/monitor-control','POST',{id,action});await refresh();if(result.pushToken)showPushToken(result.pushToken);else{closePanel();toast('Monitor updated.')}}catch(e){toast(e.message)}}
function monitorDetail(id){let d=state.devices.find(d=>d.id===id),c=d?.integration;if(!c)return;modal(`<span class="badge ${d.status.toLowerCase()}">${esc(d.status)}</span><h1>${esc(d.name)}</h1><p>${esc(d.company)} · ${esc(monitorNames[c.monitorType])}</p><p class="metric-note">${esc(c.displayEndpoint||c.host||'Incoming push heartbeat')} · Every ${c.interval}s · Timeout ${c.timeout}s · ${c.retries} retries</p>${d.monitorMessage?`<p class="${d.status==='Offline'?'error':'metric-note'}">${esc(d.monitorMessage)}</p>`:''}${heartbeats(d)}${responseChart(d)}<div class="detailgrid">${[['day','24 hours'],['week','7 days'],['month','30 days']].map(([key,label])=>`<div class="card"><small>${label} uptime</small><strong>${metric(d.availability?.[key]?.uptime)}</strong><p class="metric-note">${duration(d.availability?.[key]?.observedSeconds)} observed<br>Average ${d.availability?.[key]?.averageMs??'—'} ms</p></div>`).join('')}</div><p class="metric-note">Uptime uses observed check intervals. Unobserved gaps are excluded.</p>${d.certificateDays!=null?`<p>Certificate expires in ${d.certificateDays} days.</p>`:''}${d.dnsAnswers?`<pre>${esc(d.dnsAnswers.join('\n'))}</pre>`:''}<div class="actions"><button class="btn" data-role="admin" onclick="monitorForm(${id})">Edit</button><button class="btn" data-role="admin" onclick="monitorAction(${id},'${c.paused?'resume':'pause'}')">${c.paused?'Resume':'Pause'}</button><button class="btn" data-role="admin" onclick="monitorAction(${id},'clone')">Clone</button>${c.monitorType==='push'?`<button class="btn" data-role="admin" onclick="monitorAction(${id},'rotate-push')">Rotate push URL</button>`:`<button class="btn" data-role="write" onclick="pollDevice(${id})">Check now</button>`}<button class="btn" data-role="write" onclick="maintenanceForm(${id})">Maintenance</button><button class="btn" data-role="write" onclick="removeDevice(${id})">Delete</button></div><h2 class="section">Recent checks</h2><div class="tablewrap"><table><thead><tr><th>TIME</th><th>RESULT</th><th>RESPONSE</th></tr></thead><tbody>${(d.availability?.recent||[]).slice().reverse().map(h=>`<tr><td>${esc(new Date(h.time*1000).toLocaleString())}</td><td>${h.up===true?'Up':h.up===false?'Down':'Retrying'}</td><td>${h.responseMs??'—'} ms</td></tr>`).join('')}</tbody></table></div>`);applyRole()}
async function loadStatusPages(){try{let pages=await api('/api/status-pages');if(!$('#statusPageList'))return;$('#statusPageList').innerHTML=pages.map(p=>`<section class="card"><h2>${esc(p.title)}</h2><a href="/status/${esc(p.slug)}" target="_blank" rel="noopener">Open published status page</a><p>${p.devices.length} selected devices</p><button class="btn" data-edit-status="${esc(p.slug)}">Edit</button></section>`).join('')||'<p class="empty">No published status pages.</p>';document.querySelectorAll('[data-edit-status]').forEach(el=>el.onclick=()=>statusPageForm(pages.find(p=>p.slug===el.dataset.editStatus)))}catch(e){if($('#statusPageList'))$('#statusPageList').textContent=e.message}}
function statusPageForm(page){modal(`<h1>${page?'Edit':'Publish'} status page</h1><p class="notice">Selected device names and status will be publicly readable at the page URL. Addresses and credentials stay private.</p><form id="statusPageForm"><label for="statusTitle">Title</label><input class="field" id="statusTitle" name="title" required value="${esc(page?.title||'')}"><label for="statusSlug">URL name</label><input class="field" id="statusSlug" name="slug" pattern="[a-z0-9][a-z0-9-]{0,62}" required value="${esc(page?.slug||'')}" ${page?'readonly':''}><label for="statusDomain">Custom hostname (optional)</label><input class="field" id="statusDomain" name="domain" value="${esc(page?.domain||'')}"><p class="metric-note">Point its DNS to this server. Domain routing uses the same app port; external HTTPS requires your own certificate setup.</p><label for="statusDescription">Public description / incident notice</label><textarea class="field" id="statusDescription" name="description" maxlength="2048">${esc(page?.description||'')}</textarea><h2>Devices to publish</h2>${state.devices.map(d=>`<label class="formlabel"><input type="checkbox" name="devices" value="${d.id}" ${page?.devices.includes(d.id)?'checked':''}> ${esc(d.company)} / ${esc(d.name)}</label>`).join('')}<button class="btn primary">Publish status page</button>${page?'<button type="button" class="btn" id="removeStatusPage">Unpublish</button>':''}</form>`);$('#statusPageForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{await api('/api/status-pages','POST',{title:f.get('title'),slug:f.get('slug'),devices:f.getAll('devices').map(Number),domain:f.get('domain'),description:f.get('description')});closePanel();loadStatusPages();toast('Status page published.')}catch(e){toast(e.message)}};if(page)$('#removeStatusPage').onclick=async()=>{try{await api('/api/status-pages','POST',{slug:page.slug,delete:true});closePanel();loadStatusPages();toast('Status page unpublished.')}catch(e){toast(e.message)}}}
